CREATE TRIGGER tournament_start_time_locked_during_launch BEFORE UPDATE OF start_time ON public.tournaments FOR EACH ROW EXECUTE FUNCTION trg_lock_tournament_start_time_during_launch();
DROP TRIGGER IF EXISTS "tournaments_short_formats_never_break" ON public.tournaments;
CREATE TRIGGER tournaments_short_formats_never_break BEFORE INSERT OR UPDATE OF tournament_type, variant, synchronized_breaks ON public.tournaments FOR EACH ROW EXECUTE FUNCTION fn_short_formats_never_break();
DROP TRIGGER IF EXISTS "trg_tournaments_registered_contract_lock" ON public.tournaments;
CREATE TRIGGER trg_tournaments_registered_contract_lock BEFORE UPDATE ON public.tournaments FOR EACH ROW EXECUTE FUNCTION fn_guard_registered_tournament_contract();
DROP TRIGGER IF EXISTS "trg_tournaments_start_readiness" ON public.tournaments;
CREATE TRIGGER trg_tournaments_start_readiness BEFORE UPDATE OF status ON public.tournaments FOR EACH ROW EXECUTE FUNCTION fn_guard_tournament_start_readiness();
DROP TRIGGER IF EXISTS "zz_ca_fund_overlay_on_lock" ON public.tournaments;
CREATE TRIGGER zz_ca_fund_overlay_on_lock BEFORE UPDATE OF status ON public.tournaments FOR EACH ROW EXECUTE FUNCTION fn_ca_fund_overlay_on_lock();
DROP TRIGGER IF EXISTS "zz_freeze_launch_guard" ON public.tournaments;
CREATE TRIGGER zz_freeze_launch_guard BEFORE UPDATE OF status ON public.tournaments FOR EACH ROW WHEN (((new.status = 'RUNNING'::text) AND (old.status IS DISTINCT FROM new.status))) EXECUTE FUNCTION fn_refuse_new_entries_while_frozen();
DROP TRIGGER IF EXISTS "zzzz_freeze_registered_tournament_settlement_contract" ON public.tournaments;
CREATE TRIGGER zzzz_freeze_registered_tournament_settlement_contract BEFORE UPDATE OF variant, tournament_type, satellite_target_id, bubble_protection, buy_in_amount, guaranteed_prize ON public.tournaments FOR EACH ROW EXECUTE FUNCTION trg_freeze_registered_tournament_settlement_contract();
DROP TRIGGER IF EXISTS "trg_ca_append_only" ON public.wallet_transactions;
CREATE TRIGGER trg_ca_append_only BEFORE DELETE OR UPDATE ON public.wallet_transactions FOR EACH ROW EXECUTE FUNCTION fn_ca_journal_append_only();
DROP TRIGGER IF EXISTS "trg_ca_money_path_log" ON public.wallet_transactions;
CREATE TRIGGER trg_ca_money_path_log AFTER INSERT ON public.wallet_transactions FOR EACH ROW WHEN (((new.type = 'credit'::text) AND ((lower(COALESCE(new.category, ''::text)) = ANY (ARRAY['prize'::text, 'bounty'::text, 'refund'::text, 'tournament_prize'::text, 'tournament_refund'::text])) OR (lower(COALESCE(new.category, ''::text)) ~~ 'tourney%'::text)))) EXECUTE FUNCTION fn_ca_money_path_log();
DROP TRIGGER IF EXISTS "zz_ca_escrow_wallet_tx" ON public.wallet_transactions;
CREATE TRIGGER zz_ca_escrow_wallet_tx AFTER INSERT ON public.wallet_transactions FOR EACH ROW WHEN ((new.related_entity_id IS NOT NULL)) EXECUTE FUNCTION fn_ca_escrow_on_wallet_tx();
